var GTUNE = [40, 45, 50, 55, 59, 64];
var LOW = 48, HIGH = 72;
var HEARTBEAT_MS = 2000, LINGER_MS = 8000, TRAIL_LEN = 4;

var cur = 0, follow = 0, advance = 0, lastBar = -1, matched = false;
var shift = 0;      // the MPK's octave: 0 = default (lowest key 48), 12 = one up, -12 = one down
var hits = [], sounding = [], offTask = null;
var held = {};      // folded onto the 25 keys, for drawing
var raw = {};       // raw pitches held now, for naming (the lowest is the bass)
var released = {};  // raw pitch -> time released, for ringing notes
var shown = null;   // a chord the bridge asked to show: { label, keys, pcs }
var nowName = null, nowSince = 0, lastName = null, lastAt = 0, trail = [], drawnSig = "";

// colors (never the only signal: keys also carry letters, an R and dot markers)
var BG = [0.11, 0.115, 0.13, 1], PANEL = [0.17, 0.175, 0.2, 1];
var FG = [0.93, 0.92, 0.91, 1], MUTED = [0.6, 0.59, 0.65, 1];
var AMBER = [1.0, 0.7, 0.24, 1], TEAL = [0.44, 0.83, 0.78, 1], PINK = [1.0, 0.42, 0.6, 1];
var WKEY = [0.9, 0.9, 0.92, 1], BKEY = [0.08, 0.08, 0.1, 1], DARK = [0.07, 0.07, 0.09, 1];

function pc(n) { return ((n % 12) + 12) % 12; }
function fold(n) { while (n < LOW) n += 12; while (n > HIGH) n -= 12; return n; }
// Where a played note sits on the 25 drawn keys, given the MPK's octave. Only notes that still don't fit get folded.
function place(n) { var m = n - shift; return m >= LOW && m <= HIGH ? m : fold(m); }
// Follow the MPK's octave buttons: a note above or below the drawn keys moves the window by whole octaves.
function followOctave(n) {
  var m = n - shift;
  if (m > HIGH) shift += 12 * Math.ceil((m - HIGH) / 12);
  else if (m < LOW) shift -= 12 * Math.ceil((LOW - m) / 12);
  shift = Math.max(-48, Math.min(48, shift));
}
function setOctave(o) { shift = Math.max(-48, Math.min(48, o * 12)); relayout(); mgraphics.redraw(); }
function relayout() { held = {}; for (var k in raw) held[place(+k)] = 1; }
function now() { return new Date().getTime(); }
function col(c) { mgraphics.set_source_rgba(c[0], c[1], c[2], c[3]); }
function box(x, y, w, h, c) { col(c); mgraphics.rectangle(x, y, w, h); mgraphics.fill(); }
function rbox(x, y, w, h, r, c) { col(c); mgraphics.rectangle_rounded(x, y, w, h, r, r); mgraphics.fill(); }
function txt(s, x, y, size, c, bold) {
  mgraphics.select_font_face(bold ? "Arial Bold" : "Arial");
  mgraphics.set_font_size(size); col(c); mgraphics.move_to(x, y); mgraphics.show_text(s);
}
function ctxt(s, cx, y, size, c, bold) {
  mgraphics.select_font_face(bold ? "Arial Bold" : "Arial");
  mgraphics.set_font_size(size);
  var w = mgraphics.text_measure(s)[0];
  txt(s, cx - w / 2, y, size, c, bold);
}
function fitText(s, x, y, size, maxW, c, bold) {
  mgraphics.select_font_face(bold ? "Arial Bold" : "Arial");
  while (size > 9) { mgraphics.set_font_size(size); if (mgraphics.text_measure(s)[0] <= maxW) break; size--; }
  txt(s, x, y, size, c, bold);
}
function sortedNums(obj) { var a = []; for (var k in obj) a.push(+k); a.sort(function (x, y) { return x - y; }); return a; }

// What the keys should show: the bridge's chord if there is one, else the progression's.
function target() {
  if (shown) return { nm: shown.label, keys: shown.keys, pcs: shown.pcs, mine: false };
  var c = CH[cur];
  return { nm: c.nm, keys: c.keys, pcs: c.pcs, mine: true };
}

function heldPcs() { var s = {}; for (var k in held) s[pc(+k)] = 1; return s; }
function check() {
  var t = target(), hp = heldPcs(), got = 0, extra = 0, n = 0, k;
  for (k in hp) { n++; if (t.pcs.indexOf(+k) < 0) extra++; }
  for (var i = 0; i < t.pcs.length; i++) if (hp[t.pcs[i]]) got++;
  return { got: got, extra: extra, n: n, total: t.pcs.length };
}

// ---- naming what's played (table built from theory_name_chord's logic by build.ts) ----
function shapeOf(notes) {
  if (notes.length < 2) return null;
  var bass = pc(notes[0]), mask = 0, i;
  for (i = 0; i < notes.length; i++) mask |= 1 << ((pc(notes[i]) - bass + 12) % 12);
  var e = GEN_CHORDS[mask];
  if (!e) return null;
  var name = NAMES[(bass + e[0]) % 12] + e[1] + (e[0] ? "/" + NAMES[bass] : "");
  if (e[2]) {
    var xs = [];
    for (i = 0; i < 12; i++) if (e[2] & (1 << i)) xs.push(NAMES[(bass + i) % 12]);
    name += " add " + xs.join(" ");
  }
  return { name: name, ext: e[2] ? 1 : 0 };
}
// Notes let go together (a block chord) stop ringing when the next note starts on empty keys; arpeggios keep ringing.
function dropBlockReleases() {
  var ks = sortedNums(released), drop = [], i, j;
  for (i = 0; i < ks.length; i++)
    for (j = 0; j < ks.length; j++)
      if (i !== j && Math.abs(released[ks[i]] - released[ks[j]]) <= BLOCK_MS) { drop.push(ks[i]); break; }
  for (i = 0; i < drop.length; i++) delete released[drop[i]];
}
// Held notes, plus notes released in the last RING_MS when they complete a chord (so an arpeggio reads as one).
function soundingName() {
  var t = now(), h = sortedNums(raw), ring = [], k;
  for (k in released) {
    if (raw[k]) { delete released[k]; continue; }
    if (t - released[k] < RING_MS) ring.push(+k); else delete released[k];
  }
  var hs = h.length >= 2 ? shapeOf(h) : null;
  if (ring.length) {
    var all = h.concat(ring); all.sort(function (x, y) { return x - y; });
    var as = all.length >= 3 ? shapeOf(all) : null;
    if (as && (!hs || !as.ext)) return as.name;
  }
  return hs ? hs.name : null;
}

function tickFn() {
  var t = now(), name = soundingName();
  if (name !== nowName) { nowName = name; nowSince = t; }
  if (name && t - nowSince >= TRAIL_HOLD_MS) {
    if (trail[trail.length - 1] !== name) { trail.push(name); if (trail.length > TRAIL_LEN) trail.shift(); }
    lastName = name; lastAt = t;
  }
  var sig = (nowName || "") + "|" + (lastName && t - lastAt < LINGER_MS ? lastName : "") + "|" + trail.join(",");
  if (sig !== drawnSig) { drawnSig = sig; mgraphics.redraw(); }
}
var tick = new Task(tickFn, this);
tick.interval = 100;
tick.repeat();

var heartbeat = new Task(function () { outlet(1, "/cc/hello"); }, this);
heartbeat.interval = HEARTBEAT_MS;
heartbeat.repeat();

function notifydeleted() { tick.cancel(); heartbeat.cancel(); if (offTask) offTask.cancel(); }

// ---- messages from the patch ----
function note(p, v) {
  p = Math.round(p); v = Math.round(v);
  outlet(1, "/cc/note", p, v);
  if (v > 0) { if (!sortedNums(raw).length) dropBlockReleases(); followOctave(p); raw[p] = 1; delete released[p]; }
  else if (raw[p]) { delete raw[p]; released[p] = now(); }
  relayout();
  var s = check();
  if (s.got === s.total && s.extra === 0) matched = true;
  else if (s.n === 0) {
    if (matched && advance && !shown) cur = (cur + 1) % CH.length;
    matched = false;
  }
  tickFn();
  mgraphics.redraw();
}
function bar(b) {
  if (!follow || shown || b === lastBar || b < 1) return;
  lastBar = b;
  var next = (b - 1) % CH.length;
  if (next !== cur) { cur = next; matched = false; mgraphics.redraw(); }
}
function chord(i) { shown = null; cur = Math.max(0, Math.min(CH.length - 1, i)); matched = false; mgraphics.redraw(); }

// "show <label> <pitch>...": light these notes (from the bridge, or typed into the patch for testing)
function show() {
  var a = arrayfromargs(arguments), label = a.length ? String(a[0]) : "", keys = [], pcs = [], i;
  for (i = 1; i < a.length; i++) {
    var n = Math.round(+a[i]);
    if (isNaN(n) || n < 0 || n > 127) continue;
    var f = fold(n);
    if (keys.indexOf(f) < 0) keys.push(f);
    if (pcs.indexOf(pc(n)) < 0) pcs.push(pc(n));
  }
  if (!keys.length) return;
  keys.sort(function (x, y) { return x - y; });
  shown = { label: label || "Claude's chord", keys: keys, pcs: pcs };
  matched = false;
  mgraphics.redraw();
}
function clear() { shown = null; matched = false; mgraphics.redraw(); }
function anything() {
  var a = arrayfromargs(arguments);
  if (messagename === "/cc/show") show.apply(this, a);
  else if (messagename === "/cc/clear") clear();
}

function stopSound() {
  for (var i = 0; i < sounding.length; i++) outlet(0, sounding[i], 0);
  sounding = [];
}
function hear() {
  stopSound();
  if (offTask) offTask.cancel();
  sounding = target().keys.slice();
  for (var j = 0; j < sounding.length; j++) sounding[j] += shift; // play it in the octave the MPK is in
  for (var i = 0; i < sounding.length; i++) outlet(0, sounding[i], 90);
  offTask = new Task(stopSound, this);
  offTask.schedule(1400);
}

// ---- drawing ----
function paint() {
  var sz = mgraphics.size, W = sz[0], H = sz[1], i;
  var t = target();
  var c = CH[cur];
  hits = [];
  box(0, 0, W, H, BG);

  // left column: title, chord buttons, toggles
  txt("CHORD COACH", 10, 15, 10, AMBER, true);
  mgraphics.select_font_face("Arial Bold"); mgraphics.set_font_size(10);
  txt("E Dorian · 170", 10 + mgraphics.text_measure("CHORD COACH")[0] + 6, 15, 9, MUTED, false); // measured: Mac fonts run wider
  var bw = 68, bh = 36;
  for (i = 0; i < CH.length; i++) {
    var on = !shown && i === cur;
    var bx = 10 + (i % 2) * (bw + 6), by = 22 + Math.floor(i / 2) * (bh + 6);
    rbox(bx, by, bw, bh, 5, on ? AMBER : PANEL);
    txt(CH[i].nm, bx + 7, by + 16, 13, on ? DARK : FG, true);
    txt((i + 1) + " · " + CH[i].sub, bx + 7, by + 29, 9, on ? DARK : MUTED, false);
    hits.push({ x: bx, y: by, w: bw, h: bh, act: "chord", i: i });
  }
  var ty = 112;
  var toggles = [["Follow song bars", follow, "follow"], ["Next when I nail it", advance, "advance"]];
  for (i = 0; i < toggles.length; i++) {
    var yy = ty + i * 17;
    rbox(10, yy, 11, 11, 2, toggles[i][1] ? TEAL : PANEL);
    if (toggles[i][1]) ctxt("x", 15.5, yy + 9, 10, DARK, true);
    txt(toggles[i][0], 27, yy + 9.5, 10, toggles[i][1] ? FG : MUTED, false);
    hits.push({ x: 8, y: yy - 2, w: 140, h: 15, act: toggles[i][2] });
  }
  rbox(10, 146, 142, 18, 9, PANEL);
  ctxt("Hear chord", 81, 159, 10, FG, true);
  hits.push({ x: 10, y: 146, w: 142, h: 18, act: "hear" });

  // keyboard: MIDI 48..72
  var kx = 164, ky = 8, KW = 24, KH = 108, BW = 15, BH = 66, n, wi = 0, pos = {};
  var rootKey = t.keys[0];
  var black = function (m) { var p = pc(m); return p === 1 || p === 3 || p === 6 || p === 8 || p === 10; };
  for (n = LOW; n <= HIGH; n++) if (!black(n)) { pos[n] = kx + wi * KW; wi++; }
  for (n = LOW; n <= HIGH; n++) if (black(n)) pos[n] = pos[n - 1] + KW - BW / 2;
  var fillFor = function (m, isB) {
    if (held[m]) return PINK;
    if (m === rootKey) return AMBER;
    if (t.keys.indexOf(m) >= 0) return TEAL;
    return isB ? BKEY : WKEY;
  };
  var drawKey = function (m, isB) {
    var w = isB ? BW : KW - 1, h = isB ? BH : KH, cx = pos[m] + w / 2;
    var inChord = t.keys.indexOf(m) >= 0;
    rbox(pos[m], ky, w, h, 3, fillFor(m, isB));
    if (held[m] || inChord) ctxt(NAMES[pc(m)], cx, ky + h - 7, isB ? 8 : 10, DARK, true);
    else if (!isB && pc(m) === 0) ctxt("C", cx, ky + h - 7, 9, MUTED, false);
    if (m === rootKey) ctxt("R", cx, ky + 13, isB ? 8 : 10, DARK, true);
    if (held[m]) {
      // pressed: a filled dot if it's in the chord, a hollow ring if it isn't (shape, not just colour)
      var dy = ky + (isB ? 34 : 64), r = isB ? 4 : 5;
      col(DARK);
      mgraphics.ellipse(cx - r, dy - r, r * 2, r * 2);
      if (inChord) mgraphics.fill(); else { mgraphics.set_line_width(2); mgraphics.stroke(); }
    }
  };
  for (n = LOW; n <= HIGH; n++) if (!black(n)) drawKey(n, false);
  for (n = LOW; n <= HIGH; n++) if (black(n)) drawKey(n, true);

  // status under the keyboard
  var s = check(), msg, mc = MUTED;
  var names = [];
  for (i = 0; i < t.keys.length; i++) names.push(NAMES[pc(t.keys[i])]);
  var who = shown ? "Claude shows " : "Play ";
  if (s.n === 0) msg = who + t.nm + ":  " + names.join("  ");
  else if (s.got === s.total && s.extra === 0) { msg = t.nm + ": got it!" + (advance && !shown ? " (let go for the next one)" : ""); mc = TEAL; }
  else { msg = s.got + " of " + s.total + " notes of " + t.nm + (s.extra ? ",  " + s.extra + " not in it" : ""); mc = AMBER; }
  fitText(msg, kx, 134, 12, 270, mc, true);
  // MPK octave: follows the keys you play; the - and + buttons set it by hand
  var oct = shift / 12, ox = 444;
  txt("Octave " + (oct > 0 ? "+" + oct : oct), ox, 134, 9.5, oct ? FG : MUTED, oct !== 0);
  rbox(ox + 82 - 30, 122, 13, 14, 3, PANEL); ctxt("-", ox + 82 - 23.5, 133, 11, FG, true);
  rbox(ox + 82 - 14, 122, 13, 14, 3, PANEL); ctxt("+", ox + 82 - 7.5, 133, 11, FG, true);
  hits.push({ x: ox + 52, y: 120, w: 14, h: 18, act: "octdown" });
  hits.push({ x: ox + 68, y: 120, w: 14, h: 18, act: "octup" });
  txt("R = root (left hand)   lit + lettered = the chord   dot = you're pressing it   ring = pressed, not in it", kx, 152, 8.5, MUTED, false);

  // guitar chord box
  var gx = 544, gy = 26, SG = 12, FGAP = 18;
  txt("GUITAR", gx - 4, 15, 9, MUTED, true);
  if (!t.mine) {
    txt("No guitar shape", gx - 4, 40, 10, MUTED, false);
    txt("for this one yet", gx - 4, 54, 10, MUTED, false);
  } else {
    col(MUTED); mgraphics.set_line_width(1);
    for (i = 0; i < 6; i++) { mgraphics.move_to(gx + i * SG, gy); mgraphics.line_to(gx + i * SG, gy + 4 * FGAP); mgraphics.stroke(); }
    for (i = 0; i <= 4; i++) { mgraphics.set_line_width(i === 0 ? 3 : 1); mgraphics.move_to(gx, gy + i * FGAP); mgraphics.line_to(gx + 5 * SG, gy + i * FGAP); mgraphics.stroke(); }
    for (i = 0; i < 6; i++) {
      var fr = c.g[i], x = gx + i * SG, isRoot = fr >= 0 && pc(GTUNE[i] + fr) === c.root;
      if (fr < 0) { ctxt("x", x, gy - 4, 9, MUTED, false); continue; }
      if (fr === 0) { col(isRoot ? AMBER : TEAL); mgraphics.set_line_width(1.5); mgraphics.ellipse(x - 3.5, gy - 11, 7, 7); mgraphics.stroke(); }
      else { col(isRoot ? AMBER : TEAL); mgraphics.ellipse(x - 5, gy + (fr - 0.5) * FGAP - 5, 10, 10); mgraphics.fill(); }
      if (isRoot && fr > 0) ctxt("R", x, gy + (fr - 0.5) * FGAP + 3.5, 8, DARK, true);
    }
    ctxt(c.gn, gx + 2.5 * SG, gy + 4 * FGAP + 16, 9, FG, true);
    var shape = [];
    for (i = 0; i < 6; i++) shape.push(c.g[i] < 0 ? "x" : c.g[i]);
    ctxt(shape.join(" "), gx + 2.5 * SG, gy + 4 * FGAP + 30, 9, MUTED, false);
  }

  // bass hint
  var bxp = 628;
  txt("BASS", bxp, 15, 9, MUTED, true);
  if (t.mine) for (i = 0; i < c.bass.length; i++) txt(c.bass[i], bxp, 36 + i * 16, 10, i === 0 ? FG : MUTED, i === 0);
  else { txt("Root: " + NAMES[pc(t.keys[0])], bxp, 36, 10, FG, true); txt("play it on the E or A string", bxp, 52, 9, MUTED, false); }
  txt("SYNTH", bxp, 104, 9, MUTED, true);
  txt("Melody idea:", bxp, 120, 10, MUTED, false);
  txt("B > A > G > F#", bxp, 136, 10, FG, true);
  txt("one note per bar", bxp, 152, 9, MUTED, false);

  // what you're playing: now, or the last chord for 8 s, then the trail (oldest at the top)
  var px = 772, pw = 120, tnow = now();
  box(px - 8, 6, 1, H - 12, PANEL);
  txt("YOU'RE PLAYING", px, 15, 9, MUTED, true);
  if (nowName) fitText(nowName, px, 42, 22, pw, FG, true);
  else if (lastName && tnow - lastAt < LINGER_MS) { fitText(lastName, px, 42, 22, pw, MUTED, true); txt("last played", px, 56, 9, MUTED, false); }
  else txt("nothing yet", px, 38, 11, MUTED, false);
  txt("TRAIL  (oldest first)", px, 78, 9, MUTED, true);
  for (i = 0; i < trail.length; i++) {
    var newest = i === trail.length - 1;
    fitText((i + 1) + ". " + trail[i] + (newest ? "  < newest" : ""), px, 94 + i * 17, 11, pw, newest ? FG : MUTED, newest);
  }
}

function onclick(x, y) {
  for (var i = 0; i < hits.length; i++) {
    var h = hits[i];
    if (x >= h.x && x <= h.x + h.w && y >= h.y && y <= h.y + h.h) {
      if (h.act === "chord") { shown = null; cur = h.i; matched = false; hear(); }
      else if (h.act === "follow") { follow = follow ? 0 : 1; lastBar = -1; }
      else if (h.act === "advance") advance = advance ? 0 : 1;
      else if (h.act === "hear") hear();
      else if (h.act === "octdown") setOctave(shift / 12 - 1);
      else if (h.act === "octup") setOctave(shift / 12 + 1);
      mgraphics.redraw();
      return;
    }
  }
}

function onresize() { mgraphics.redraw(); }
